//! Rendering the model as Rust source text.
//!
//! The definitions' prose is the crate's documentation, so every quoted
//! passage goes inside a `text` code block: rustdoc leaves a code block alone,
//! and the CDM's text is full of markdown links, HTML breaks and bare brackets
//! that it would otherwise read as markup.

use std::fmt::Write;

use crate::lower::{Model, RustType, Table};

/// The banner every generated file opens with, the SPDX tags under it.
///
/// The `@generated` marker holds the first line, so the tags of the crate's
/// own licence follow the banner block
/// (<https://spdx.dev/learn/handling-license-info/>).
pub const BANNER: &str = "// @generated by omop-cdm-codegen from OHDSI/CommonDataModel v5.4.3. DO NOT EDIT.\n// Change the emitter (tools/omop-cdm-codegen) and regenerate.\n// SPDX-FileCopyrightText: Ruben Talstra\n// SPDX-License-Identifier: BUSL-1.1\n";

/// The four DDL files, in the order `ferrobridge cdm init` applies them: the
/// tables, then the primary keys, the indices and the foreign-key constraints.
pub const DDL_FILES: [DdlFile; 4] = [
    DdlFile {
        constant: "DDL",
        file: "OMOPCDM_postgresql_5.4_ddl.sql",
        what: "The `CREATE TABLE` statement of every CDM v5.4 table",
    },
    DdlFile {
        constant: "PRIMARY_KEYS",
        file: "OMOPCDM_postgresql_5.4_primary_keys.sql",
        what: "The primary-key constraint of every CDM v5.4 table",
    },
    DdlFile {
        constant: "INDICES",
        file: "OMOPCDM_postgresql_5.4_indices.sql",
        what: "The indices OHDSI's script creates over the CDM v5.4 tables",
    },
    DdlFile {
        constant: "CONSTRAINTS",
        file: "OMOPCDM_postgresql_5.4_constraints.sql",
        what: "The foreign-key constraints between the CDM v5.4 tables",
    },
];

/// One embedded DDL file: the constant that carries it, the file it is copied
/// from, and the summary line of its documentation.
#[derive(Debug, Clone, Copy)]
pub struct DdlFile {
    /// The name of the `pub const` in the generated `ddl` module.
    pub constant: &'static str,
    /// The file name, under `ddl/` in the crate and under the vendored tree.
    pub file: &'static str,
    /// The summary line of the constant's documentation.
    pub what: &'static str,
}

/// Renders `src/generated/mod.rs`: the table modules and the index over every
/// table's column metadata.
///
/// # Errors
///
/// Returns [`std::fmt::Error`] when writing to the output string fails.
pub fn render_mod(model: &Model) -> Result<String, std::fmt::Error> {
    let mut out = String::new();
    out.push_str(BANNER);
    out.push_str(
        "//! The generated OMOP Common Data Model v5.4 layer: one module per\n\
         //! table, each with its row type and its column metadata, and the\n\
         //! embedded OHDSI PostgreSQL DDL.\n\
         //!\n\
         //! The tables are the complete set the definitions carry, across the\n\
         //! `CDM`, `VOCAB` and `RESULTS` schemas\n\
         //! (<https://ohdsi.github.io/CommonDataModel/cdm54.html>).\n\
         #![expect(\n\
         \x20   clippy::struct_field_names,\n\
         \x20   reason = \"the CDM names a column after its table and suffixes every key with _id\"\n\
         )]\n",
    );
    out.push('\n');
    out.push_str("pub mod ddl;\n");
    let mut modules: Vec<&str> = model
        .tables
        .iter()
        .map(|table| table.name.as_str())
        .collect();
    modules.sort_unstable();
    for module in modules {
        writeln!(out, "pub mod {module};")?;
    }
    out.push('\n');
    writeln!(
        out,
        "/// Every table of the OMOP Common Data Model v5.4, in definition order.\n\
         ///\n\
         /// The order is the order of `OMOP_CDMv5.4_Table_Level.csv`, which is\n\
         /// the order OHDSI's rendered DDL creates the tables in.\n\
         pub static TABLES: [crate::meta::TableMeta; {}] = [",
        model.tables.len()
    )?;
    for table in &model.tables {
        writeln!(out, "    crate::meta::TableMeta {{")?;
        writeln!(out, "        name: \"{}\",", table.name)?;
        writeln!(
            out,
            "        cdm_schema: crate::meta::CdmSchema::{},",
            table.schema.variant()
        )?;
        writeln!(
            out,
            "        columns: &{}::{},",
            table.name,
            table.columns_static()
        )?;
        writeln!(out, "    }},")?;
    }
    out.push_str("];\n");
    Ok(out)
}

/// Renders `src/generated/ddl.rs`: the four DDL files, embedded verbatim.
///
/// # Errors
///
/// Returns [`std::fmt::Error`] when writing to the output string fails.
pub fn render_ddl() -> Result<String, std::fmt::Error> {
    let mut out = String::new();
    out.push_str(BANNER);
    out.push_str(
        "//! OHDSI's rendered PostgreSQL DDL for OMOP CDM v5.4, embedded\n\
         //! verbatim.\n\
         //!\n\
         //! OHDSI renders these files from the same definitions through a\n\
         //! dialect layer that sits outside them, so they are vendored rather\n\
         //! than generated (`ddl/PROVENANCE.md`). Each one still carries the\n\
         //! `@cdmDatabaseSchema` placeholder; [`crate::ddl::with_schema`]\n\
         //! substitutes it.\n",
    );
    for ddl in DDL_FILES {
        out.push('\n');
        writeln!(out, "/// {}.", ddl.what)?;
        writeln!(out, "///")?;
        writeln!(out, "/// The verbatim text of `{}`.", ddl.file)?;
        writeln!(
            out,
            "pub const {}: &str = include_str!(\"../../ddl/{}\");",
            ddl.constant, ddl.file
        )?;
    }
    Ok(out)
}

/// Renders one table's module: its row type and its column metadata.
///
/// # Errors
///
/// Returns [`std::fmt::Error`] when writing to the output string fails.
pub fn render_table(table: &Table) -> Result<String, std::fmt::Error> {
    let mut out = String::new();
    out.push_str(BANNER);
    writeln!(
        out,
        "//! The `{}` table of the OMOP Common Data Model v5.4 (`{}` schema).",
        table.name,
        table.schema.as_str()
    )?;
    out.push('\n');
    writeln!(out, "/// One row of the `{}` table.", table.name)?;
    let table_prose = [
        ("Table description", table.description.as_deref()),
        ("User guidance", table.user_guidance.as_deref()),
        ("ETL conventions", table.etl_conventions.as_deref()),
    ];
    write_prose(&mut out, "OMOP_CDMv5.4_Table_Level.csv", &table_prose)?;
    out.push_str("#[derive(Debug, Clone, PartialEq)]\n");
    writeln!(out, "pub struct {} {{", table.type_name)?;
    for column in &table.columns {
        let mut summary = format!(
            "    /// The `{}` column: `{}`",
            column.name, column.cdm_datatype
        );
        if column.required {
            summary.push_str(", required");
        } else {
            summary.push_str(", optional");
        }
        if column.primary_key {
            summary.push_str(", the primary key");
        }
        if let Some((fk_table, fk_column)) = &column.foreign_key {
            write!(summary, ", referencing `{fk_table}.{fk_column}`")?;
        }
        summary.push_str(".\n");
        out.push_str(&summary);
        let column_prose = [
            ("User guidance", column.user_guidance.as_deref()),
            ("ETL conventions", column.etl_conventions.as_deref()),
        ];
        write_indented_prose(&mut out, "OMOP_CDMv5.4_Field_Level.csv", &column_prose)?;
        let rust_type = column.rust_type.name();
        let rust_type = if column.required {
            rust_type
        } else {
            format!("Option<{rust_type}>")
        };
        writeln!(out, "    pub {}: {rust_type},", column.name)?;
    }
    out.push_str("}\n\n");
    render_columns(&mut out, table)?;
    Ok(out)
}

/// Renders one table's column-metadata static.
fn render_columns(out: &mut String, table: &Table) -> Result<(), std::fmt::Error> {
    writeln!(
        out,
        "/// The columns of the `{}` table, in definition order.",
        table.name
    )?;
    writeln!(
        out,
        "pub static {}: [crate::meta::ColumnMeta; {}] = [",
        table.columns_static(),
        table.columns.len()
    )?;
    for column in &table.columns {
        writeln!(out, "    crate::meta::ColumnMeta {{")?;
        writeln!(out, "        name: \"{}\",", column.name)?;
        writeln!(out, "        cdm_datatype: \"{}\",", column.cdm_datatype)?;
        writeln!(
            out,
            "        rust_type_name: \"{}\",",
            metadata_type_name(column.rust_type)
        )?;
        writeln!(out, "        required: {},", column.required)?;
        writeln!(out, "        primary_key: {},", column.primary_key)?;
        match &column.foreign_key {
            Some((fk_table, fk_column)) => writeln!(
                out,
                "        foreign_key: Some((\"{fk_table}\", \"{fk_column}\")),"
            )?,
            None => writeln!(out, "        foreign_key: None,")?,
        }
        writeln!(
            out,
            "        cdm_schema: crate::meta::CdmSchema::{},",
            table.schema.variant()
        )?;
        writeln!(out, "    }},")?;
    }
    out.push_str("];\n");
    Ok(())
}

/// Returns the type name the metadata carries, without the `crate::value::`
/// path the row struct spells.
fn metadata_type_name(rust_type: RustType) -> String {
    rust_type
        .name()
        .strip_prefix("crate::value::")
        .map_or_else(|| rust_type.name(), str::to_owned)
}

/// Writes the definitions' prose as a doc comment, at no indentation.
fn write_prose(
    out: &mut String,
    source: &str,
    sections: &[(&str, Option<&str>)],
) -> Result<(), std::fmt::Error> {
    write_prose_at(out, "", source, sections)
}

/// Writes the definitions' prose as a doc comment, indented one level for a
/// struct field.
fn write_indented_prose(
    out: &mut String,
    source: &str,
    sections: &[(&str, Option<&str>)],
) -> Result<(), std::fmt::Error> {
    write_prose_at(out, "    ", source, sections)
}

/// Writes the quoted sections of the definitions as a `text` code block.
///
/// The block keeps the specification's own wording, and rustdoc reads none of
/// it as markup.
fn write_prose_at(
    out: &mut String,
    indent: &str,
    source: &str,
    sections: &[(&str, Option<&str>)],
) -> Result<(), std::fmt::Error> {
    if sections.iter().all(|(_, text)| text.is_none()) {
        return Ok(());
    }
    writeln!(out, "{indent}///")?;
    writeln!(out, "{indent}/// The definitions' own text (`{source}`):")?;
    writeln!(out, "{indent}///")?;
    writeln!(out, "{indent}/// ```text")?;
    let mut first = true;
    for (heading, text) in sections {
        let Some(text) = text else { continue };
        if !first {
            writeln!(out, "{indent}///")?;
        }
        first = false;
        writeln!(out, "{indent}/// {heading}:")?;
        for line in fenced(text) {
            if line.is_empty() {
                writeln!(out, "{indent}///")?;
            } else {
                writeln!(out, "{indent}///   {line}")?;
            }
        }
    }
    writeln!(out, "{indent}/// ```")?;
    Ok(())
}

/// Splits the definitions' text into lines safe to put inside a `text` code
/// block: carriage returns dropped, trailing spaces trimmed, and a run of
/// backticks that would close the block broken up.
fn fenced(text: &str) -> Vec<String> {
    text.replace('\r', "\n")
        .lines()
        .map(|line| line.trim_end().replace("```", "` ` `"))
        .collect()
}
